using System.Text.Json;using KDPika.LicenseSdk;using System.Net;
var checks=0;void Assert(bool v){if(!v)throw new Exception("Application policy check failed");checks++;}
foreach(var scope in new[]{"both","desktop","web"})foreach(var type in new[]{"desktop","web"}){Assert(ApplicationAccess.Allowed(JsonSerializer.SerializeToElement(new{application_access=scope,application_type=type}),type)==(scope=="both"||scope==type));Assert(!ApplicationAccess.Allowed(JsonSerializer.SerializeToElement(new{application_access=scope,application_type=type=="web"?"desktop":"web"}),type));}
foreach(var raw in new[]{"null","true","{}","\"other\""})Assert(!ApplicationAccess.Allowed(JsonDocument.Parse("{\"application_access\":"+raw+"}").RootElement,"desktop"));
var folder=Path.Combine(Path.GetTempPath(),"kdpika-app-context-"+Guid.NewGuid());Directory.CreateDirectory(folder);
try{using var http=new HttpClient(new Capture());await using var desktop=new LicenseClient("app_fixture",storageDir:folder,httpClient:http,applicationType:"desktop");await using var web=new LicenseClient("app_fixture",storageDir:folder,httpClient:http,applicationType:"web");Assert(desktop.InstallationId!=web.InstallationId);var method=typeof(LicenseClient).GetMethod("RequestAsync",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)!;await (Task)method.Invoke(desktop,new object?[]{HttpMethod.Get,"/api/v1/public-key",null,new Dictionary<string,string>(),CancellationToken.None})!;Assert(Capture.Context=="desktop");Console.WriteLine($"PASS {checks} checks");}finally{Directory.Delete(folder,true);}
sealed class Capture:HttpMessageHandler{public static string? Context;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken c){Context=r.Headers.GetValues("X-Application-Type").Single();return Task.FromResult(new HttpResponseMessage(HttpStatusCode.Forbidden){Content=new StringContent("{\"success\":false,\"error\":{\"code\":\"APPLICATION_NOT_ALLOWED\"}}")});}}
